{"content": "// 按 zstd 魔数切分多帧，逐帧解压 DSH session v4 jsonl
const fs = require('fs');
const zlib = require('zlib');

const file = process.argv[2];
const mode = process.argv[3] || 'tail';
const arg = process.argv[4];
const n = Number(process.argv[5] || 5);

const buf = fs.readFileSync(file);
const magic = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
const offs = [];
let i = 0;
while ((i = buf.indexOf(magic, i)) >= 0) { offs.push(i); i++; }

const lines = [];
for (let k = 0; k < offs.length; k++) {
  const end = k + 1 < offs.length ? offs[k + 1] : buf.length;
  try {
    const s = zlib.zstdDecompressSync(buf.subarray(offs[k], end)).toString('utf8');
    s.split('\n').filter((l) => l.trim()).forEach((l) => lines.push(l));
  } catch (e) {
    console.error('frame ' + k + ' failed: ' + e.message);
  }
}
console.error('[frames=' + offs.length + ' lines=' + lines.length + ']');

if (mode === 'head') lines.slice(0, n).forEach((l) => console.log(l));
else if (mode === 'tail') lines.slice(-n).forEach((l) => console.log(l));
else if (mode === 'grep') {
  const re = new RegExp(arg, 'i');
  let c = 0;
  lines.forEach((l, idx) => {
    if (re.test(l)) {
      c++;
      if (c <= n) console.log('#' + idx + ' ' + l.slice(0, 4000));
    }
  });
  console.error('[matches=' + c + ']');
} else if (mode === 'types') {
  const t = new Map();
  for (const l of lines) {
    try { const o = JSON.parse(l); const k = o.type + (o.payload && o.payload.kind ? ':' + o.payload.kind : ''); t.set(k, (t.get(k) || 0) + 1); } catch {}
  }
  console.log([...t.entries()].map(([k, v]) => k + '=' + v).join('\n'));
}
", "file_path": "D:\downloads\algs4-master\algs4-master\out\zstd-frames.js"}

