const fs = require('fs');
const path = require('path');

const roots = process.argv.slice(2);
const NEEDLES = ['PRIMARY SUBJECT', 'IDE Context', 'is viewing this file'];

function scanFile(p) {
  let st;
  try { st = fs.statSync(p); } catch { return; }
  if (st.size > 40 * 1024 * 1024) return;
  let buf;
  try { buf = fs.readFileSync(p); } catch { return; }
  for (const n of NEEDLES) {
    const i = buf.indexOf(Buffer.from(n));
    if (i >= 0) {
      const ctx = buf.subarray(Math.max(0, i - 160), i + 200).toString('utf8').replace(/[^\x20-\x7E]/g, '.');
      console.log('HIT ' + p + ' | ' + n + '\n    ' + ctx + '\n');
    }
  }
}

function walk(dir, depth) {
  if (depth > 8) return;
  let ents;
  try { ents = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of ents) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, depth + 1);
    else if (e.isFile()) scanFile(p);
  }
}

for (const r of roots) walk(r, 0);
console.log('scan done');
